B.bYd=new A.hx("1. OBJETIVO",null)
B.bXq=new A.kB("Esta Politica de Privacidade explica como a DeliGo recolhe, utiliza, partilha e protege dados pessoais de clientes, estafetas, restaurantes e administradores no ambito da utilizacao da aplicacao e servicos associados.",null)
B.bYl=new A.hx("2. RESPONSAVEL PELOS DADOS",null)
B.bXA=new A.kB("A Deligo Triunfal, LDA atua como responsavel pelo tratamento dos dados pessoais recolhidos atraves da plataforma DeliGo.",null)
B.bYn=new A.hx("3. DADOS QUE PODEMOS RECOLHER",null)
B.bYW=new A.y3("3.1 Dados de conta",null)
B.aL0=s(["Nome e dados de perfil","Numero de telefone","Email, quando fornecido","Foto de perfil, quando enviada"],t.s)
B.bVQ=new A.kx(B.aL0,null)
B.bZ5=new A.y3("3.2 Dados de verificacao e compliance",null)
B.aPf=s(["Documentos de identificacao e respetiva informacao","Selfie ou foto para verificacao","Dados necessarios para prevencao de fraude e cumprimento legal"],t.s)
B.bVs=new A.kx(B.aPf,null)
B.bYY=new A.y3("3.3 Dados de pedidos e pagamentos",null)
B.aGT=s(["Historico de pedidos","Endereco de entrega e coordenadas relacionadas","Valores, taxas e estado das transacoes","Registos de wallet, depositos e levantamentos"],t.s)
B.bVw=new A.kx(B.aGT,null)
B.bYZ=new A.y3("3.4 Dados de localizacao",null)
B.aEH=s(["Localizacao aproximada e precisa para mapas e cobertura","Rastreamento do pedido e do estafeta","Calculo de rotas e tempos estimados"],t.s)
B.bVo=new A.kx(B.aEH,null)
B.bYU=new A.y3("3.5 Comunicacoes e dados tecnicos",null)
B.aIb=s(["Mensagens de chat e suporte","Notificacoes push e preferencias","Identificadores da aplicacao, analytics, crash logs e diagnosticos"],t.s)
B.bVq=new A.kx(B.aIb,null)
B.bYK=new A.hx("4. COMO UTILIZAMOS OS DADOS",null)
B.aOB=s(["Criar e gerir contas","Processar pedidos, entregas e levantamentos","Processar pagamentos e reconciliacoes","Ativar chat, notificacoes e suporte","Prevenir fraude e reforcar a seguranca","Cumprir obrigacoes legais, fiscais e regulatorias","Melhorar o desempenho e a confiabilidade da plataforma"],t.s)
B.bVA=new A.kx(B.aOB,null)
B.bYg=new A.hx("5. PARTILHA DE DADOS",null)
B.bXu=new A.kB("Clientes, restaurantes e estafetas podem ver os dados minimos necessarios para executar um pedido. Tambem podemos partilhar dados com prestadores de pagamentos, infraestrutura, analytics, suporte tecnico e autoridades competentes quando exigido por lei.",null)
B.bYe=new A.hx("6. RETENCAO",null)
B.bXH=new A.kB("Mantemos os dados pelo tempo necessario para prestar o servico, cumprir requisitos legais, prevenir fraude, resolver disputas e manter a integridade operacional e financeira da plataforma.",null)
B.bYI=new A.hx("7. SEGURANCA",null)
B.bXm=new A.kB("Adotamos medidas tecnicas e organizacionais para proteger os dados, incluindo controlos de acesso, autenticacao, validacoes do lado do servidor e monitorizacao. Nenhum sistema e 100% seguro, mas trabalhamos continuamente para reduzir riscos.",null)
B.bYE=new A.hx("8. DIREITOS DO UTILIZADOR",null)
B.aFw=s(["Solicitar acesso aos seus dados","Solicitar correcao de dados","Solicitar eliminacao ou encerramento de conta, quando possivel","Retirar consentimentos, quando o tratamento depender de consentimento"],t.s)
B.bVS=new A.kx(B.aFw,null)
B.bXF=new A.kB("Os pedidos de eliminacao de conta podem ser feitos diretamente na aplicacao DeliGo, na secao Configuracoes. Pedidos com saldo, pedidos ativos, disputas ou obrigacoes legais podem passar por revisao manual antes da eliminacao definitiva.",null)
B.bYx=new A.hx("9. TECNOLOGIAS SEMELHANTES A COOKIES",null)
B.bXl=new A.kB("A aplicacao pode utilizar identificadores e tecnologias semelhantes para manter sessao, prevenir fraude, suportar analytics e melhorar o servico.",null)
B.bYJ=new A.hx("10. ALTERACOES",null)
B.bXo=new A.kB("Podemos atualizar esta politica periodicamente. A versao mais recente deve estar disponivel nos canais oficiais da DeliGo.",null)
B.a8Y=new A.hx("11. CONTACTO",null)
